/*
 * Offline-first service worker for Carromscore.
 *
 * Strategy: on install, fetch `asset-manifest.json` (generated by
 * scripts/build-manifest.mjs after every `astro build`), then
 * `cache.addAll` every asset + page URL it lists. That gets the whole
 * app into the cache on the first successful load, so subsequent
 * visits work fully offline — no more "half a page" when the network
 * flakes out mid-JS-fetch.
 *
 * On repeat visits: `fetch` handler serves from cache for anything in
 * the precache set, network-first for navigation requests (so a new
 * deploy propagates fast), cache-first for anything else with a
 * network fallback.
 *
 * `activate` cleans up caches from prior versions (identified by name
 * mismatch). CACHE_NAME is refreshed by the manifest's buildId so any
 * new build produces a new cache — old caches drop cleanly.
 *
 * Prior versions of this file precached only the HTML shell and
 * relied on runtime caching to pick up JS/CSS on first hit. That
 * bricked the app for first-time visitors on a bad-network moment
 * (bug reported 2026-08-13). This version precaches everything the
 * asset-manifest names, up-front.
 */

// Bump on every release. Included in the cache name below, so a
// version change purges old caches on activate. Also bumped between
// release cycles when a change to this file's byte content matters
// enough that we want browsers to re-install the SW without waiting
// for a full deploy — the SDK detects the diff and re-fires install.
const APP_VERSION = '3.3.0-beta.4';

// Base URL is derived from the SW's own location so the same source
// works on both main (/carromscore/) and beta (/carromscore/beta/).
// Falls back to /carromscore/ if the URL parse fails for any reason.
function baseUrl() {
  try {
    // Strip the filename, keep the trailing slash.
    return self.location.pathname.replace(/[^/]+$/, '');
  } catch {
    return '/carromscore/';
  }
}
const BASE = baseUrl();
const MANIFEST_URL = `${BASE}asset-manifest.json`;
const OFFLINE_URL = BASE;

// Assets in this list are added to PRECACHE alongside the manifest,
// as a safety net if manifest fetch fails or the SW is running an
// older build than the manifest expects. Keep small.
const FALLBACK_PRECACHE = [
  BASE,
  `${BASE}manifest.webmanifest`,
  `${BASE}favicon.svg`,
];

// Cache name incorporates the app version — activate() below deletes
// every cache whose name doesn't match, so bumping this string on a
// new build purges everything old. The manifest's buildId gets
// appended at install() so a same-version rebuild also busts.
let currentCacheName = `carromscore-${APP_VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    let manifest = null;
    try {
      const res = await fetch(MANIFEST_URL, { cache: 'no-cache' });
      if (res.ok) manifest = await res.json();
    } catch {
      // network-dead first install. We'll cache what we can and hope
      // the runtime handler picks up the rest on the next visit.
    }
    if (manifest && manifest.buildId) {
      currentCacheName = `carromscore-${manifest.version}-${manifest.buildId}`;
    }
    const cache = await caches.open(currentCacheName);
    // De-dupe with a Set so an asset that's also a page (e.g. root)
    // doesn't try to double-add. addAll is atomic — one 404 aborts
    // the whole thing — so we drop known-optional entries into a
    // best-effort second pass rather than blocking install on them.
    const primary = new Set(FALLBACK_PRECACHE);
    if (manifest) {
      for (const u of manifest.assets || []) primary.add(u);
      for (const u of manifest.pages || []) primary.add(u);
    }
    try {
      await cache.addAll(Array.from(primary));
    } catch (e) {
      // At least one URL 404'd or the network failed mid-addAll.
      // Fall back to a best-effort loop so we cache what we can.
      for (const url of primary) {
        try {
          const res = await fetch(url, { cache: 'no-cache' });
          if (res.ok) await cache.put(url, res.clone());
        } catch {
          // move on; runtime handler will catch stragglers
        }
      }
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names
        .filter((n) => n !== currentCacheName)
        .map((n) => caches.delete(n)),
    );
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;

  // Cross-origin requests: don't intercept. Third-party assets
  // (Google avatar CDN at lh3.googleusercontent.com, Firebase RTDB
  // long-poll, gstatic, etc.) should go straight to the network
  // without SW routing. Intercepting produces opaque responses that
  // Chrome sometimes marks as `net::ERR_FAILED` when the request
  // is passed back through the SW pipeline — for the Google avatar
  // that surfaces as a broken image in the signed-in pill.
  //
  // Anything that DID need offline support for a cross-origin URL
  // (e.g. Firebase's `.info/connected` long-poll) is handled by the
  // Firebase SDK's own in-memory buffering, not by us.
  const reqUrl = new URL(req.url);
  if (reqUrl.origin !== self.location.origin) return;

  // Navigation requests: network-first with a cached-shell fallback
  // for the matching route (query-string-agnostic). Users on a good
  // network get the latest deploy immediately; users on a bad network
  // get the precached HTML for their target route so /score/?...
  // opens the scoreboard, not the home page.
  //
  // Route-matching detail: caches.match(req) is exact-URL, so a
  // request for /score/?mid=abc never matches the cached /score/
  // entry. We strip the query and re-match against the route path.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const res = await fetch(req);
        const cache = await caches.open(currentCacheName);
        // Cache under the query-stripped URL so future offline hits
        // to the same route match regardless of params.
        const cleanUrl = new URL(req.url);
        cleanUrl.search = '';
        cache.put(cleanUrl.toString(), res.clone());
        return res;
      } catch {
        // Try exact match first (survives the pre-query-strip era).
        let cached = await caches.match(req);
        if (cached) return cached;
        // Query-stripped fallback: /score/?x=y → try /score/.
        const cleanUrl = new URL(req.url);
        cleanUrl.search = '';
        cached = await caches.match(cleanUrl.toString());
        if (cached) return cached;
        // Last resort: the home shell so at least something renders.
        const offline = await caches.match(OFFLINE_URL);
        if (offline) return offline;
        return Response.error();
      }
    })());
    return;
  }

  // asset-manifest.json: always try the network first so a new build
  // is picked up by the next install(). Fallback to cache lets an
  // offline SW re-install work if we ever re-fire install.
  if (req.url.endsWith('/asset-manifest.json')) {
    event.respondWith((async () => {
      try {
        const res = await fetch(req, { cache: 'no-cache' });
        const cache = await caches.open(currentCacheName);
        cache.put(req, res.clone());
        return res;
      } catch {
        const cached = await caches.match(req);
        return cached || Response.error();
      }
    })());
    return;
  }

  // Everything else: cache-first with network fallback + cache-fill.
  event.respondWith(cacheFirst(req));
});

async function cacheFirst(req) {
  const cached = await caches.match(req);
  if (cached) return cached;
  try {
    const res = await fetch(req);
    if (res.status === 200 && (res.type === 'basic' || res.type === 'cors')) {
      const copy = res.clone();
      caches.open(currentCacheName).then((cache) => cache.put(req, copy));
    }
    return res;
  } catch {
    return Response.error();
  }
}
